output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_entering_single_file_with_cart",
    "text": "A customer must not enter a single-file shelf aisle while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "singleFileShelfAisle",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle",
    "text": "After returning from a single-file shelf aisle without the cart, the customer is obliged to pick the cart back up at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "leaveSingleFileWithoutCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "S"
            ]
          },
          "post": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "pickUpCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileWithoutCart",
      "discharge": "pickUpCartAtMouth"
    }
  },
  {
    "id": "cart_required_for_open_shelf_interactions",
    "text": "When interacting with a shelf from an open aisle rather than a single-file shelf aisle, the customer must have a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "openShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfAccess",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_for_single_file_shelf_pickup",
    "text": "Shelf items located in single-file aisles must be picked up without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_roaming_without_cart_except_cart_free_zones",
    "text": "Customers should not travel without their cart except at the entrance, at narrow-aisle cart parking mouths, or inside the single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartFreeTravelZone": {
          "or": [
            "entranceCartArea",
            "narrowAisleMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartFreeTravelZone"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_from_cart_bay",
    "text": "At the start of a shopping trip, the customer is obliged to take a cart from the cart bay before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              "cartBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCart"
    }
  },
  {
    "id": "interact_only_at_shelves_or_cart_stations",
    "text": "Customers may interact only with shelves or at designated cart-handling stations such as the cart bay and narrow-aisle parking mouths.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartHandlingStation": {
          "or": [
            "cartBay",
            "narrowAisleMouth"
          ]
        },
        "permittedInteractionPlace": {
          "or": [
            "adjShelf",
            "cartHandlingStation"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "permittedInteractionPlace"
          }
        ]
      }
    }
  }
]
